mapper.select:
WITH LatestDeviceData AS ( SELECT Name, ElectricEnergy, ROW_NUMBER() OVER (PARTITION BY Name ORDER BY UpdateTime DESC) as rn FROM RSWS_TempMonitor_Copy WHERE Workshop = '103冷压' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT SUM(ElectricEnergy) as totalElectricEnergy FROM LatestDeviceData WHERE rn = 1

SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '103冷压' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
ORDER BY Name, UpdateTime DESC

choose.when:
WITH DailyBoundaries AS ( SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayEnd FROM ( SELECT TOP ( DATEDIFF(DAY, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '103冷压' AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = '103冷压' AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '103冷压' AND inner_tm.UpdateTime >= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = '103冷压' AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = '103冷压' AND inner_tm.UpdateTime >= db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY DayStart ) SELECT COALESCE(SUM( CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL

choose.otherwise:
WITH DeviceList AS ( SELECT DISTINCT DeviceID, Name FROM RSWS_TempMonitor_Copy WHERE Workshop = '103冷压' AND ElectricEnergy IS NOT NULL ), DeviceBounds AS ( SELECT dl.DeviceID, dl.Name,
#{startTime} DATEADD(HOUR,-24,GETDATE()) AS StartTime,
-- 为每个设备找到结束时间以后最近的一条数据的时间，如果没有则用 endTime 内的最近一条时间 COALESCE( (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '103冷压' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name AND t.ElectricEnergy IS NOT NULL
AND t.UpdateTime > #{endTime}
ORDER BY t.UpdateTime ASC), (SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy t WHERE t.Workshop = '103冷压' AND t.DeviceID = dl.DeviceID AND t.Name = dl.Name AND t.ElectricEnergy IS NOT NULL
AND t.UpdateTime >= #{startTime}
AND t.UpdateTime <= #{endTime}
ORDER BY t.UpdateTime DESC) ) AS ActualEndTime FROM DeviceList dl ), DeviceEnergyData AS ( SELECT db.DeviceID, db.Name, -- 获取开始时间的电能值 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor_Copy t_start WHERE t_start.Workshop = '103冷压' AND t_start.DeviceID = db.DeviceID AND t_start.Name = db.Name AND t_start.UpdateTime >= db.StartTime AND t_start.ElectricEnergy IS NOT NULL ORDER BY t_start.UpdateTime ASC) AS StartEnergy,
-- 获取结束时间的电能值 (SELECT TOP 1 ElectricEnergy FROM RSWS_TempMonitor_Copy t_end WHERE t_end.Workshop = '103冷压' AND t_end.DeviceID = db.DeviceID AND t_end.Name = db.Name AND t_end.UpdateTime <= db.ActualEndTime AND t_end.ElectricEnergy IS NOT NULL ORDER BY t_end.UpdateTime DESC) AS EndEnergy FROM DeviceBounds db WHERE db.ActualEndTime IS NOT NULL ) SELECT COALESCE(SUM( CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceEnergyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL

mapper.select:
SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = '103冷压'
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
AND DeviceID LIKE CONCAT('%', #{deviceId}, '%')
AND Name LIKE CONCAT('%', #{name}, '%')
ORDER BY UpdateTime DESC
